sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    if (current.bed.changes() && !current.bed.nil()) {
        var bedGr = current.bed.getRefRecord();
        if (bedGr.isValidRecord()) {
            var bedStatus = bedGr.getValue('status');

            // '1' = Available
            if (bedStatus != '1') {
                // If '2' (Reserved), allow if actively reserved for this patient
                var isReservedForThisPatient = false;
                if (bedStatus == '2') {
                    var resGr = new GlideRecord('x_2223823_apollo_0_bed_reservations');
                    resGr.addQuery('bed', current.getValue('bed'));
                    resGr.addQuery('patient', current.getValue('patient'));
                    resGr.addQuery('status', '1'); // Active
                    resGr.setLimit(1);
                    resGr.query();
                    if (resGr.hasNext()) {
                        isReservedForThisPatient = true;
                    }
                }

                if (!isReservedForThisPatient) {
                    gs.addErrorMessage('Cannot assign bed: Bed "' + bedGr.getDisplayValue('bed_number') + '" is currently ' + bedGr.status.getDisplayValue() + '. Assignment is only permitted for Available beds.');
                    current.setAbortAction(true);
                    return;
                }
            }
        }
    }

})(current, previous);
